using System;
using System.IO;
using System.Windows.Interop;
using System.Windows.Media.Imaging;

namespace CopyRecord
{
    internal static class AppIcon
    {
        private static string GetBase64()
        {
            var sb = new System.Text.StringBuilder();
            sb.Append(@"");
            return sb.ToString();
        }

        public static byte[] GetIconBytes()
        {
            return Convert.FromBase64String(GetBase64());
        }

        public static System.Windows.Media.ImageSource CreateBitmapImage()
        {
            using (System.Drawing.Icon icon = CreateDrawingIcon())
            {
                var src = Imaging.CreateBitmapSourceFromHIcon(icon.Handle, System.Windows.Int32Rect.Empty,
                    BitmapSizeOptions.FromWidthAndHeight(32, 32));
                src.Freeze();
                return src;
            }
        }

        public static System.Drawing.Icon CreateDrawingIcon(int size = 32)
        {
            using (var ms = new MemoryStream(GetIconBytes()))
            {
                return new System.Drawing.Icon(ms, size, size);
            }
        }
    }
}